<?php $edit=isset($animal['id']);$a=fn(string $k,string $default='')=>e((string)($animal[$k]??$default)); ?>
<div class="admin-pagehead"><div><span class="micro-label">FICHA DEL ANIMAL</span><h1><?= $edit?'Editar ficha':'Registrar nuevo animal' ?></h1><p>Los campos obligatorios deben completarse antes de guardar.</p></div><a class="btn btn-outline" href="/admin/animales">← Volver al listado</a></div>
<div class="animal-editor-grid"><section class="admin-panel"><h2>Información del animal</h2><form method="post" action="<?= $edit?'/admin/animales/'.(int)$animal['id'].'/editar':'/admin/animales' ?>" class="editor-form"><?= csrf_field() ?><div class="form-pair"><label>Nombre *<input name="nombre" maxlength="80" required value="<?= $a('nombre') ?>"></label><label>Especie *<input name="especie" maxlength="50" required value="<?= $a('especie') ?>" placeholder="Perro, gato..."></label></div><div class="form-pair"><label>Raza<input name="raza" maxlength="80" value="<?= $a('raza') ?>"></label><label>Edad aproximada (meses)<input name="edad_aproximada_meses" type="number" min="0" max="1200" value="<?= $a('edad_aproximada_meses') ?>"></label></div><div class="form-pair"><label>Sexo<select name="sexo"><?php foreach(['desconocido'=>'No determinado','macho'=>'Macho','hembra'=>'Hembra'] as $v=>$lab):?><option value="<?= e($v) ?>" <?= ($animal['sexo']??'desconocido')===$v?'selected':'' ?>><?= e($lab) ?></option><?php endforeach ?></select></label><label>Tamaño<select name="tamano"><?php foreach(['no_determinado'=>'No determinado','pequeno'=>'Pequeño','mediano'=>'Mediano','grande'=>'Grande'] as $v=>$lab):?><option value="<?= e($v) ?>" <?= ($animal['tamano']??'no_determinado')===$v?'selected':'' ?>><?= e($lab) ?></option><?php endforeach ?></select></label></div><div class="form-pair"><label>Fecha de rescate<input type="date" name="fecha_rescate" value="<?= $a('fecha_rescate') ?>"></label><label>Lugar de rescate (uso interno)<input name="lugar_rescate" maxlength="150" value="<?= $a('lugar_rescate') ?>"></label></div><label>Resumen público *<textarea maxlength="255" name="resumen" required><?= $a('resumen') ?></textarea></label><label>Historia<textarea name="historia" rows="6"><?= $a('historia') ?></textarea></label><div class="form-pair"><label>Estado de salud<select name="estado_salud"><?php foreach(['pendiente_evaluacion','en_tratamiento','en_recuperacion','estable'] as $v):?><option value="<?= e($v) ?>" <?= ($animal['estado_salud']??'pendiente_evaluacion')===$v?'selected':'' ?>><?= e(str_replace('_',' ',$v)) ?></option><?php endforeach ?></select></label><label>Estado de adopción<select name="estado_adopcion"><?php foreach(['no_disponible','disponible','en_evaluacion','adoptado'] as $v):?><option value="<?= e($v) ?>" <?= ($animal['estado_adopcion']??'no_disponible')===$v?'selected':'' ?>><?= e(str_replace('_',' ',$v)) ?></option><?php endforeach ?></select></label></div><button type="submit" class="btn btn-primary">Guardar ficha ↗</button></form></section>
<aside class="admin-panel"><h2>Fotografías</h2><?php if(!$edit):?><div class="empty">Guarda primero la ficha para habilitar las fotografías.</div><?php else: ?><p>Almacén privado: <code>storage/app/public/animales</code>. El sistema sirve los archivos desde una ruta segura.</p><div class="photo-gallery"><?php foreach($photos as $photo):?><div><img src="<?= e(asset($photo['ruta'])) ?>" alt="<?= e($photo['texto_alternativo']) ?>" loading="lazy"><?php if((int)$photo['es_principal']===1):?><span class="chip chip-soft">Principal</span><?php endif ?></div><?php endforeach ?></div><form class="upload-form" action="/admin/animales/<?= (int)$animal['id'] ?>/foto" method="post" enctype="multipart/form-data"><?= csrf_field() ?><label>Seleccionar fotografía (JPG/PNG/WEBP, hasta 5 MB)<input type="file" name="foto" accept="image/jpeg,image/png,image/webp" required data-preview-image></label><img class="upload-preview" alt="Vista previa" hidden><label>Texto alternativo<input type="text" name="texto_alternativo" maxlength="150" placeholder="Descripción accesible de la fotografía"></label><button type="submit" class="btn btn-outline">Subir fotografía ↥</button></form><hr><form method="post" action="/admin/animales/<?= (int)$animal['id'] ?>/archivar" data-confirm="El animal dejará de mostrarse en el catálogo público. Se conservará su historial."><?= csrf_field() ?><button type="submit" class="btn btn-danger">Archivar animal</button></form><?php endif ?></aside></div>
